"use strict";
const express = require("express");
const app = express();
app.use(express.json());
const notes = [];
app.get("/api/notes", (_req, res) => res.json({ donnees: notes }));
app.post("/api/notes", (req, res) => {
  if (typeof req.body?.titre !== "string" || !req.body.titre.trim()) return res.status(400).json({ erreur: "titre requis" });
  const note = { id: notes.length + 1, titre: req.body.titre.trim() };
  notes.push(note);
  return res.status(201).json(note);
});
app.listen(3000, () => console.log("http://localhost:3000/api/notes"));
